	@ParameterizedTest
	@ValueSource(booleans = { false, true })
	void newRawOwnerRejectsCompletedGenerationBeforeMutation(boolean inline) throws Exception {
		Path target = directory.resolve("owner");
		LmdbStoreConfig config = config(inline, Profile.CURRENT);
		loadCanonical(target, config);
		Map<String, String> before = hashes(target);
		assertThrows(SailException.class, () -> {
			try (var ignored = new LmdbNativeBulkStore(target, config)) {
				throw new AssertionError("a completed nonempty generation admitted a new raw owner");
			}
		});
		assertEquals(before, hashes(target), "raw-owner rejection cannot alter completed bytes");
		System.out.println("QUALIFY_PHASE=NEW_RAW_OWNER_REJECTED_COMPLETED_GENERATION, path=" + target);
		DomainQualificationAssertions.verify(target, config, model(), PREDICATES, true);
	}

	private static LmdbBulkLoader.Builder canonicalBuilder(Path target, LmdbStoreConfig config) {
		return LmdbBulkLoader.builder(target, config)
				.partitionCount(4)
				.workers(1)
				.memoryBudgetBytes(MEMORY)
				.maxOpenFiles(FILES);
	}

	private static void loadCanonical(Path target, LmdbStoreConfig config) throws Exception {
		load(canonicalBuilder(target, config));
	}

	private static void load(LmdbBulkLoader.Builder builder) throws IOException {
		ByteArrayOutputStream data = new ByteArrayOutputStream();
		List<Statement> duplicates = new ArrayList<>(model());
		duplicates.addAll(model());
		Rio.write(duplicates, data, RDFFormat.NQUADS);
		LmdbBulkLoader.Result result = builder.build()
				.load(new ByteArrayInputStream(data.toByteArray()), BASE,
						RDFFormat.NQUADS);
		assertEquals(16L, result.parsedStatements());
		assertEquals(8L, result.storedStatements());
	}

	private static LmdbStoreConfig config(boolean inline, Profile profile) {
		LmdbStoreConfig config = new LmdbStoreConfig("spoc,posc,ospc").setTripleTermIndexes("spoc,cspo,posc")
				.setInlineLiterals(inline)
				.setForceSync(true)
				.setFrontierEstimatorMode(FrontierEstimatorMode.OFF)
				.setPredicateGuaranteeIndexEnabled(profile != Profile.DISABLED)
				.setPredicateGuaranteeIndexAutoRebuild(profile != Profile.AUTO_REBUILD_OFF);
		config.setExperimentalQueryOptimizations(false);
		if (profile == Profile.EXCLUDED) {
			config.setPredicateGuaranteeExcludedPredicates(String.join(",",
					PREDICATES.stream().map(IRI::stringValue).toList()));
		}
		return config;
	}

	private static List<Statement> model() {
		List<Value> objects = List.of(VF.createIRI(BASE + "old-iri"), VF.createLiteral("old words"),
				VF.createLiteral("007", XSD.INT), VF.createTripleTerm(VF.createIRI(BASE + "outer"),
						VF.createIRI(BASE + "component"), VF.createTripleTerm(VF.createIRI(BASE + "inner"),
								VF.createIRI(BASE + "component"), VF.createLiteral("nested", "en"))));
		List<Statement> rows = new ArrayList<>();
		for (int i = 0; i < objects.size(); i++) {
			for (String context : List.of("first", "second")) {
				rows.add(VF.createStatement(VF.createIRI(BASE + "loaded-" + i), PREDICATES.get(i), objects.get(i),
						VF.createIRI(BASE + context)));
			}
		}
		return rows;
	}

	/**
	 * Builds all valid canonical streams; no generation token, ID, marker or certificate is constructed by the test.
	 */
	private static void writeRaw(Path target, LmdbStoreConfig config, List<Statement> model, RawRoute route)
			throws Exception {
		Path workspace = Files.createDirectory(target.resolveSibling("raw-staging"));
		CanonicalStagedInput staged;
		try (var stager = new CanonicalStatementStager(workspace, config, 4, FILES, MEMORY, BulkCompression.NONE)) {
			for (Statement statement : model) {
				stager.writeStatement(statement);
				stager.writeStatement(statement);
			}
			staged = stager.stagedInput();
		}
		var dependencies = ValueDependencyCollector.collect(staged, workspace, 4, FILES, config,
				BulkCompression.NONE, () -> false);
		var dictionary = PartitionValueDictionaryBuilder.build(staged, dependencies, workspace, 4, MEMORY, FILES,
				config, BulkCompression.NONE, () -> false);
		var spool = ResolvedIdQuadSpool.build(staged, dictionary, workspace, FILES, MEMORY,
				BulkCompression.NONE, () -> false);
		var resolved = ResolvedValueRecords.build(dictionary, workspace, FILES, MEMORY, config,
				BulkCompression.NONE, () -> false);
		try (var scheduler = new BulkTaskScheduler(1, MEMORY, FILES)) {
			var values = ValueStoreBulkRecords.build(resolved, workspace, MEMORY, FILES, BulkCompression.NONE,
					() -> false, scheduler, LmdbStoreFormat.forNewStore(config));
			if (route == RawRoute.BEFORE_PREPARATION_INTERRUPTION) {
				IOException stop = new IOException(
						"test stops after every raw stream and before canonical preparation");
				assertSame(stop, assertThrows(IOException.class, () -> NativeStoreWriter.write(target, config,
						LmdbStoreFormat.forNewStore(config), values, spool, staged, MEMORY, FILES, 2, Long.MAX_VALUE,
						BulkCompression.NONE, () -> false, scheduler, () -> {
							System.out.println("QUALIFY_PHASE=REAL_WRITER_ALL_RAW_STREAMS_BEFORE_COMPLETION");
							throw stop;
						})));
				return;
			}
			try (var statements = StatementIndexBulkRecords.build(spool, workspace, config.getTripleIndexes(),
					MEMORY, FILES, BulkCompression.NONE, () -> false, scheduler);
					var terms = TripleTermIndexBulkRecords.build(values.tripleTerms(), workspace,
							config.getTripleTermIndexes(), MEMORY, FILES, BulkCompression.NONE, () -> false, scheduler);
					var store = new LmdbNativeBulkStore(target, config)) {
				appendRecords(store, values.mainRecords(), false);
				appendRecords(store, values.referenceCounts(), true);
				for (var run : terms.runs()) {
					var iterator = tuples(run.tuples()).iterator();
					store.appendTripleTermIndex(run.specification(), tuple -> {
						if (!iterator.hasNext()) {
							return false;
						}
						System.arraycopy(iterator.next(), 0, tuple, 0, 4);
						return true;
					}, 2, Long.MAX_VALUE);
				}
				if (config.getValueHashCacheEnabled()) {
					var iterator = tuples(values.valueHashes()).iterator();
					store.appendValueHashes(tuple -> {
						if (!iterator.hasNext()) {
							return false;
						}
						System.arraycopy(iterator.next(), 0, tuple, 0, 2);
						return true;
					});
				}
				store.syncNamespaces();
				for (var run : statements.runs()) {
					long count;
					if (run.tuples() != null) {
						var iterator = tuples(run.tuples()).iterator();
						count = store.appendExplicitIndex(run.specification(), tuple -> {
							if (!iterator.hasNext()) {
								return false;
							}
							System.arraycopy(iterator.next(), 0, tuple, 0, 4);
							return true;
						}, 2, Long.MAX_VALUE);
					} else {
						var iterator = records(run.encodedRecords()).iterator();
						count = store.appendExplicitEncodedIndex(run.specification(),
								() -> iterator.hasNext() ? iterator.next() : null, 2, Long.MAX_VALUE);
					}
					assertEquals(8L, count, "each canonical index contains all unique quads");
				}
				var iterator = contextCounts(statements.contexts()).iterator();
				store.appendContexts(tuple -> {
					if (!iterator.hasNext()) {
						return false;
					}
					System.arraycopy(iterator.next(), 0, tuple, 0, 2);
					return true;
				}, 2, Long.MAX_VALUE);
			}
		}
	}

	private static void appendRecords(LmdbNativeBulkStore store, ExternalByteKeySorter.SortedRecordFile input,
			boolean counts) throws Exception {
		var iterator = records(input).iterator();
		ValueStore.BulkRecordSource source = () -> iterator.hasNext() ? iterator.next() : null;
		if (counts) {
			store.appendReferenceCounts(source, 2, Long.MAX_VALUE);
		} else {
			store.appendValueRecords(source, 2, Long.MAX_VALUE);
		}
	}

	private static List<ValueStore.BulkRecord> records(ExternalByteKeySorter.SortedRecordFile input) throws Exception {
		List<ValueStore.BulkRecord> records = new ArrayList<>();
		input.forEach((key, value) -> records.add(new ValueStore.BulkRecord(key.clone(), value.clone())));
		return records;
	}

	/** Matches NativeStoreWriter's grouping of one sorted context occurrence per unique statement. */
	private static List<long[]> contextCounts(ExternalLongTupleSorter.SortedTupleFile input) throws Exception {
		List<long[]> counts = new ArrayList<>();
		input.forEach(row -> {
			if (!counts.isEmpty() && counts.getLast()[0] == row[0]) {
				long[] previous = counts.getLast();
				previous[1] = Math.addExact(previous[1], 1L);
			} else {
				counts.add(new long[] { row[0], 1L });
			}
		});
		return counts;
	}

	private static List<long[]> tuples(ExternalLongTupleSorter.SortedTupleFile input) throws Exception {
		List<long[]> tuples = new ArrayList<>();
		input.forEach(tuple -> tuples.add(tuple.clone()));
		return tuples;
	}

	private static Map<String, String> hashes(Path root) throws Exception {
		Map<String, String> result = new TreeMap<>();
		try (var paths = Files.walk(root)) {
			for (Path path : paths.filter(Files::isRegularFile).toList()) {
				result.put(root.relativize(path).toString(),
						HexFormat.of()
								.formatHex(MessageDigest.getInstance("SHA-256").digest(Files.readAllBytes(path))));
			}
		}
		return result;
	}
